import fs from 'node:fs';
import {createPublicClient,http} from '../enclave/node_modules/viem/_esm/index.js';
import {privateKeyToAccount} from '../enclave/node_modules/viem/_esm/accounts/index.js';
import {FileStore,sessionFromRecord} from '../enclave/sdk/sessions/dist/node.mjs';
const host=JSON.parse(fs.readFileSync('/home/steven/Projects/enclave/metal/config.json'));
const account=privateKeyToAccount(host.registryKey);
const pc=createPublicClient({transport:http('https://mainnet.base.org',{timeout:15000})});
const store=new FileStore(),record=await store.load(store.activeId());
record.handle={...record.handle,rpc:'https://mainnet.base.org',relay:''};
const session=await sessionFromRecord(record);
const status=await session.status();
const catABI=JSON.parse(fs.readFileSync(new URL('../enclave/contracts/EnclaveAppCatalog.abi.json',import.meta.url)));
const regABI=JSON.parse(fs.readFileSync(new URL('../enclave/contracts/EnclaveRegistry.abi.json',import.meta.url)));
const catalog='0x18419ca2b502d423a8de6269aeee171a378626e3';
const registry='0x868eB7fc5B5A84B2FF082eafc9bf40b7AAc5CCAC';
const app=await pc.readContract({address:catalog,abi:catABI,functionName:'getApp',args:[status.apps[0]]});
const index=BigInt(app.versionCount)-1n;
const version=await pc.readContract({address:catalog,abi:catABI,functionName:'getVersion',args:[status.apps[0],index]});
const enclaveId=await pc.readContract({address:registry,abi:regABI,functionName:'idOf',args:[host.publicUrl]});
const schema=Number(await pc.readContract({address:registry,abi:regABI,functionName:'registrySchema'}));
if(schema<1||schema>5)throw Error('unsupported registry schema');
regABI.find(x=>x.name==='get').outputs[0].components.length=[0,7,9,10,11,13][schema];
const registered=await pc.readContract({address:registry,abi:regABI,functionName:'get',args:[enclaveId]});
console.log(JSON.stringify({operator:account.address,ethWei:String(await pc.getBalance({address:account.address})),session:{vault:record.handle.vault,sid:record.handle.sid,live:status.live,apps:status.apps,balance6:String(status.balance6)},app:{slug:app.slug,index,version},enclave:{id:enclaveId,...registered}},(_,v)=>typeof v==='bigint'?String(v):v,2));
